mapper.insert:
INSERT INTO T_STOCK_PRICE
(  STOCK_ID
  ,TRADE_DATE
  ,OPEN_PRICE
  ,HIGH_PRICE
  ,LOW_PRICE
  ,CLOSE_PRICE
  ,VOLUME
  ,INS_DAY
) VALUES (
   #{stockId}
  ,#{tradeDate}
  ,#{openPrice}
  ,#{highPrice}
  ,#{lowPrice}
  ,#{closePrice}
  ,#{volume}
  ,NOW()
)
ON CONFLICT (STOCK_ID, TRADE_DATE)
DO UPDATE
SET  OPEN_PRICE  = EXCLUDED.OPEN_PRICE
    ,HIGH_PRICE  = EXCLUDED.HIGH_PRICE
    ,LOW_PRICE   = EXCLUDED.LOW_PRICE
    ,CLOSE_PRICE = EXCLUDED.CLOSE_PRICE
    ,VOLUME      = EXCLUDED.VOLUME
    ,UPT_DAY     = NOW()
